from pathlib import Path
p=Path('build_v2.py').read_text()
p=p.replace('from edl import FULL,VERT',"import importlib.util,os\nspec=importlib.util.spec_from_file_location('english_edl',ROOT/'edl-en.py');edl=importlib.util.module_from_spec(spec);spec.loader.exec_module(edl)\nRAW=Path(os.environ.get('PP_MASK_DIR',ROOT/'masked-en'))")
p=p.replace("folder=ROOT/'segments'/tag", "folder=ROOT/'segments-en'/tag")
p=p.replace("if src=='stock':", "if src.startswith('open-'):inp=Path.home()/'Videos/pp-recording/masked'/(src+'.mp4')\n elif src=='stock':")
p=p.replace("def build(lang,vertical):", "def build(lang,vertical,variant):")
p=p.replace("tag=lang+('-v' if vertical else '');plan=VERT if vertical else FULL;dur=sum(p['d'] for p in plan)", "tag=lang+('-v' if vertical else '')+'-'+variant;plan=edl.plan(vertical,variant);dur=sum(p['d'] for p in plan)")
p=p.replace("outs.append(render_one(lang,vertical,i,p));", "outs.append(render_one(lang,vertical,('open-'+variant) if i==0 else i,p));")
p=p.replace("out=folder/f'{i:02}.mp4'", "out=folder/(f'{i:02}.mp4' if isinstance(i,int) else i+'.mp4')")
p=p.replace('{"-60s" if vertical else ""}.mp4', '{"-60s" if vertical else ""}-{variant}.mp4')
p=p.replace("jobs=[('ar',False),('en',False),('ar',True),('en',True)]", "jobs=[('en',False,'anim'),('en',True,'anim')]")
p=p.replace("if len(sys.argv)>1:jobs=[(sys.argv[1],len(sys.argv)>2 and sys.argv[2]=='v')]", "if len(sys.argv)>1:jobs=[('en',sys.argv[1]=='v',sys.argv[2] if len(sys.argv)>2 else 'anim')]")
p=p.replace("list(pool.map(lambda x:build(*x),jobs))", "list(pool.map(lambda x:build(*x),jobs))\n if len(sys.argv)==1:\n  for v in (False,True):build('en',v,'clip')")
Path('build_en.py').write_text(p)
